export function getUnitsForLevel(level) {
  const lc = LEVELS_CONFIG.find(l => l.level === level);
  if (!lc) return [];
  return lc.units.map(u => ({
    ...u,
    vocab: lc.vocab.filter(v => v.unitNumber === u.unitNumber)
  }));
}

// Backward compatibility
export const UNITS = getUnitsForLevel('A1');